### 含错误的代码框架
```javascript
// 柯里化过滤条件生成函数，参数声明顺序为：(userLevel, city, browseTimeMin, categoryCountMin)
const makeFilter = (userLevel) => (city) => (browseTimeMin) => (categoryCountMin) => {
  return (log) => {
    const date = new Date(log.date);
    const isInQ1 = date.getFullYear() === 2024 && date.getMonth() >= 0 && date.getMonth() <= 2;
    return isInQ1 
      && log.userLevel === userLevel 
      && log.city === city 
      && log.browseTime >= browseTimeMin 
      && log.browseCategoryCount >= categoryCountMin;
  };
};

// 柯里化聚合函数生成函数，参数声明顺序为：(timeRangeStart, timeRangeEnd, filterFunc)
const makeAggregator = (timeRangeStart) => (timeRangeEnd) => (filterFunc) => {
  // 高阶函数：接收原始日志列表，返回聚合后的统计结果
  return (logs) => {
    const validLogs = logs.filter(filterFunc);
    const groupMap = validLogs.reduce((acc, log) => {
      const key = `${log.city}_${log.userLevel}`;
      if (!acc[key]) acc[key] = { totalTime: 0, activeDays: new Set() };
      acc[key].totalTime += log.browseTime;
      acc[key].activeDays.add(log.date);
      return acc;
    }, {});
    return Object.entries(groupMap).map(([key, val]) => ({
      group: key,
      avgDailyTime: Math.round(val.totalTime / val.activeDays.size)
    }));
  };
};

// 错误调用代码
const q1Filter = makeFilter(30)(2)("VIP")("北京");
const q1Aggregator = makeAggregator("2024-01-01")("2024-03-31")(q1Filter);
const result = q1Aggregator(allLogs);
```

某生鲜电商平台需要实现多维度折扣计算模块，严格遵循函数式编程的高阶函数与柯里化范式，具体规则、约束及参考实现如下：
### 规则与约束
1. 折扣计算必须严格按「基础满减→品类券抵扣→会员等级折扣」的顺序依次执行，后一层折扣基于前一层的计算结果计算，且最终实付金额最低为0元，保留2位小数（四舍五入）；
2. 基础满减为阶梯就高规则：满100元减10元，满200元减30元，满300元减50元，无更高档位，即订单金额满足多个档位时仅减去最高档位的优惠，例如订单金额250元时仅减30元，而非10+30元；
3. 品类券为阶梯叠加规则：满50元减5元，满100元减12元，满150元减20元，即订单金额满足多个档位时，优惠金额可累加，例如订单金额160元时共减5+12+20=37元；
4. 会员等级折扣为固定比例：普通会员（等级标识1）享9折，黄金会员（等级标识2）享8折，钻石会员（等级标识3）享7折；
5. 要求实现柯里化函数`curriedDiscountCalculator`，固定为3层柯里化，每层仅接收1个参数：
   - 第1层接收基础满减规则数组（格式为`[[threshold, discount], ...]`，按threshold升序排列），返回第2层函数；
   - 第2层接收品类券规则数组（格式同基础满减），返回第3层函数；
   - 第3层接收会员等级映射对象（格式为`{levelIdentifier: discountRate, ...}`），返回最终计算函数；
   - 最终计算函数仅接收订单原始金额（正整数，单位：元），返回实付金额。
### 参考实现
```javascript
function curriedDiscountCalculator(baseRules) {
  // 基础满减计算（就高）
  const calcBaseDiscount = (amount) => {
    let discount = 0;
    for (const [threshold, dis] of baseRules) {
      if (amount >= threshold) discount = dis;
    }
    return discount;
  };
  return function(couponRules) {
    // 品类券计算（错误：实现为就高而非叠加）
    const calcCouponDiscount = (amount) => {
      let discount = 0;
      for (const [threshold, dis] of couponRules) {
        if (amount >= threshold) discount = dis; // 错误点1：覆盖而非累加
      }
      return discount;
    };
    // 错误点2：第三层柯里化返回的函数接收2个参数，不符合题目要求的单参数，且内部写死使用普通会员折扣
    return function(memberMap, amount) {
      const afterBase = amount - calcBaseDiscount(amount);
      const afterCoupon = afterBase - calcCouponDiscount(afterBase);
      // 写死使用等级1的折扣，未根据传入的会员等级动态计算
      return Math.round(afterCoupon * (memberMap[1] || 0.9) * 100) / 100;
    };
  };
}
```
### 问题要求
该参考实现通过了「订单金额350元、普通会员」的测试用例（输出252.00元），但存在微妙错误，不符合题目要求的柯里化范式，且在「订单金额160元、钻石会员」的场景下输出错误结果（正确结果应为79.10元）。请定位所有错误并修正参考实现，同时说明每个错误导致的逻辑问题。

你正在开发电商平台的商品库存扣减核心服务，需满足以下严格约束：
1. 商品库存为int类型，初始值为10000，单笔订单购买数量范围1~9999，不允许超过当前库存，库存扣减后不允许为负数
2. 支持订单幂等性：同一订单号（长度不超过32位的字符串）重复提交，仅允许扣减一次库存
3. 支持订单取消逻辑：仅未发货订单取消时可回滚对应库存，已发货订单取消不回滚库存，订单状态枚举为：0-待支付、1-待发货、2-已发货、3-已完成、4-已取消
4. 并发场景下需绝对避免超卖，库存操作响应时间≤50ms，支持每秒1000次请求
5. 错误码规范：-1 库存不足、-2 订单重复提交、-3 系统异常、0 操作成功
现有如下Java代码实现，其中存在**边界条件未覆盖、异常处理逻辑错误、并发逻辑缺陷**三类微妙错误，请你完成以下任务：
（1）定位代码中所有错误点，说明每个错误的触发场景（需给出具体数值/条件示例）
（2）针对每个错误给出符合约束的修复方案
（3）验证修复后的代码在以下边界场景下的执行结果：
  场景A：当前库存为500，提交购买600的订单
  场景B：同一订单号"ORDER_20240520_001"连续提交2次
  场景C：当前库存为100，并发提交2笔购买数量均为60的订单
