现有错误代码片段：
```java
@Service
public class StockService {
    // 本地内存存储已处理订单号，用于幂等校验
    private Set<String> processedOrderIds = new HashSet<>();
    @Autowired
    private GoodsMapper goodsMapper;
    @Autowired
    private OrderMapper orderMapper;
    @Transactional(rollbackFor = Exception.class)
    public int deductStock(String orderId, int buyNum, String goodsId) {
        // 幂等校验
        if (processedOrderIds.contains(orderId)) {
            return -2;
        }
        // 查询商品库存
        Goods goods = goodsMapper.selectById(goodsId);
        int stock = goods.getStock();
        // 库存校验
        if (stock < buyNum) {
            return -1;
        }
        // 扣减库存
        int newStock = stock - buyNum;
        goods.setStock(newStock);
        goodsMapper.updateById(goods);
        // 记录已处理订单
        processedOrderIds.add(orderId);
        // 校验订单状态，仅未发货订单取消可回滚（此处为扣减逻辑，状态校验为取消时调用）
        return 0;
    }
    @Transactional(rollbackFor = Exception.class)
    public int cancelOrder(String orderId, String goodsId) {
        // 查询订单状态
        Order order = orderMapper.selectById(orderId);
        if (order.getStatus() != 1) { // 非待发货状态
            return -3;
        }
        // 回滚库存
        Goods goods = goodsMapper.selectById(goodsId);
        int newStock = goods.getStock() + order.getBuyNum();
        goods.setStock(newStock);
        goodsMapper.updateById(goods);
        // 更新订单状态为已取消
        order.setStatus(4);
        orderMapper.updateById(order);
        return 0;
    }
}
